-- 일본어판(/ja/) 표시값 칸. 영문 칸(20261001000001_en_columns.sql)과 같은 자리에 둔다.
--
-- 공개 화면이 DB 를 먼저 읽으므로 번역을 정적 JSON 에만 두면 보이지 않는다. 그래서 원본 테이블에 일본어 칸을 둔다.
-- 비어 있으면 일본어판은 영문 칸을, 영문 칸도 비어 있으면 한국어 원문을 보여 준다.
--
-- labs·repair_shops 의 name·region·address 원문은 그대로 둔다. 지역 필터·딥링크 슬러그·네이버 지도 검색이
-- 한국어 값을 키로 쓰기 때문이다. 일본어 칸은 화면 표시에만 쓴다.

ALTER TABLE public.films        ADD COLUMN IF NOT EXISTS description_ja text;

ALTER TABLE public.labs         ADD COLUMN IF NOT EXISTS name_ja text;
ALTER TABLE public.labs         ADD COLUMN IF NOT EXISTS address_ja text;
ALTER TABLE public.labs         ADD COLUMN IF NOT EXISTS features_ja text;

ALTER TABLE public.repair_shops ADD COLUMN IF NOT EXISTS name_ja text;
ALTER TABLE public.repair_shops ADD COLUMN IF NOT EXISTS address_ja text;
ALTER TABLE public.repair_shops ADD COLUMN IF NOT EXISTS specialty_ja text;
ALTER TABLE public.repair_shops ADD COLUMN IF NOT EXISTS description_ja text;

-- ── 번역 채우기 (2026-10-02, AI 번역) ──
-- 일본어 칸이 비어 있는 행만 채운다. 관리 화면에서 나중에 고친 값은 다시 적용해도 덮지 않는다.
-- 행 목록은 영문 마이그레이션 두 개(20261001000001·20261001000002)와 같다. 한국어 원문이 저장소에 있는 행은
-- 한국어에서, 관리 화면에서만 등록한 행은 영문 칸에서 옮겼다.

-- 필름 소개글 161종
UPDATE public.films SET description_ja = $ja$室内から日差しの良い屋外まで、一本で無難にこなすISO 400カラーネガ。C-41現像。24枚撮り単位で手軽に出回っており、気負わず一本持ち出せる日常用の選択肢。$ja$ WHERE slug = '1shot400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$2018年に生産終了した富士フイルムの第1世代Acros。非常に細かな粒子と豊かなトーンのグラデーション、14分まで相反則不軌がほとんどない長時間露光の強さで、日本のモノクロフィルムの頂点を極めたライン。現在はAcros IIがその系譜を継いでいる。$ja$ WHERE slug = 'acros1' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムAcrosの再発売版。非常に細かく緻密な粒子とクリーンなトーンが特徴で、日本のモノクロフィルムの代表格とされる。長時間露光でも相反則不軌がほとんどない点も強み。$ja$ WHERE slug = 'acros2' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Adoxの伝統的なモノクロフィルムの再発売版。大きめの粒状感とクラシックなトーンカーブが、ヴィンテージなモノクロのムードを生む。$ja$ WHERE slug = 'adoxchs100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Adoxの超高解像度モノクロ。微粒子と豊かなグレートーンで、風景や大判プリントに強い。$ja$ WHERE slug = 'adoxhr50' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$2023年に発売されたAdoxのカラーライン。自然な発色と細かな粒子で、入門用カラー市場に新しく加わったライン。$ja$ WHERE slug = 'adoxmission200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kodakが航空測量用に作ったカラーフィルムをスチル写真用にリブランドした特殊なライン。柔らかな発色、微粒子、非常に広いラチチュードが特徴。Reflx LabやFlicFilmなど複数のブランドで詰め替えて流通している。$ja$ WHERE slug = 'aerocolor' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Agfaの低感度モノクロ。APX 400の姉妹で、より細かく緻密な粒子のため、風景や静物で滑らかなモノクロを求めるときに選ぶ。AgfaPhotoブランドの再発売ライン。$ja$ WHERE slug = 'agfaapx100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Agfaのクラシックなモノクロフィルムの現行ライン。2017年にAgfaPhotoブランドで再発売されて以来、深いコントラストと粗い粒状感で、ドキュメンタリーやストリートのモノクロでよく見かけるフィルム。$ja$ WHERE slug = 'agfaapx400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Agfaの日常用カラーリバーサル(E-6)フィルム。彩度の高い色と豊かなディテールで風景や旅行写真によく使われ、後期にはFujiの乳剤を詰め替えて流通していた。現在は生産終了。$ja$ WHERE slug = 'agfactprecisa100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$商業的に発売された唯一のモノクロリバーサルフィルム。現像するとネガではなくポジになり、ライトボックスに載せればそのまま見える。専用のAP-44処理が必要なため、指定ラボにしか出せなかった。粒子がとても細かく黒が深い一方、中間調が薄いという評価もつきまとう。ISO 200が基準で、100から1600まで調整できた。2005年に生産終了。$ja$ WHERE slug = 'agfascala200x' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Agfaの高彩度プロ用カラーネガ。豊かな発色と深いシャドーのディテールで、風景やポートレートに長く使われた。Vistaラインとともに2018年頃に生産終了。$ja$ WHERE slug = 'agfaultra100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Agfa Vistaラインの低感度カラーネガ。柔らかなコントラストと自然な肌色で、日常スナップや屋外のカラープリント用に長く使われたライン。Vista 200/400とともに2018年に生産終了。$ja$ WHERE slug = 'agfavista100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Agfaの日常用カラーネガ。淡いマゼンタと落ち着いた彩度が特徴で、コストパフォーマンスの良い日常用カラーとして長く使われた。2018年に生産終了し、現在はコレクターの間で取引されている。$ja$ WHERE slug = 'agfavista200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Agfa Vistaラインの高感度の姉妹フィルム。Vista 200より一段粗い粒状感と涼しげな色合いで、曇りの日や室内の日常に強かった。2018年に生産終了。$ja$ WHERE slug = 'agfavista400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$米国のFreestyleが、チェコFomaのFomapan 100をリブランドして販売するモノクロフィルム。中身はFomapan 100と同じで、北米ではより安く出回る。安価なモノクロを気兼ねなく使い倒すのに向く。$ja$ WHERE slug = 'aristaedu100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$米国のFreestyleが、チェコFomaのFomapan 200をリブランドして販売するモノクロフィルム。中身はFomapan 200と同じで、北米ではより安く出回る。安価なモノクロを気兼ねなく使い倒すのに向く。$ja$ WHERE slug = 'aristaedu200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$米国のFreestyleが、チェコFomaのFomapan 400をリブランドして販売するモノクロフィルム。中身はFomapan 400と同じで、北米ではより安く出回る。安価なモノクロを気兼ねなく使い倒すのに向く。$ja$ WHERE slug = 'aristaedu400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$ISO 13の超低感度シネマ用モノクロフィルム。日差しの下でも比較的長い露光が必要だが、ほぼ粒子のない滑らかなトーンと絵画的なグラデーションが得られる。三脚と根気が似合うフィルム。$ja$ WHERE slug = 'babylonkino13' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$フランスBerggerの二層乳剤モノクロフィルム。二層の銀粒子が生む豊かなトーンのグラデーションと深いシャドーの描写が特徴。$ja$ WHERE slug = 'bergger400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$ORWOのシネマフィルムをベースにしたモノクロライン。ベルリンの街並みを思わせる深いグレーのグラデーションと、クラシック映画のトーンが特徴。都市の空気を一枚に収めたいときによく合う。$ja$ WHERE slug = 'berlinkino400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$C-41のカラー現像で処理するモノクロフィルム。一般のカラーラボでモノクロを仕上げてもらえたため、モノクロ入門の入り口だった。2014年に生産終了。$ja$ WHERE slug = 'bw400cn' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムで最も手頃なカラーネガのライン。涼しげな緑と青緑の描写が生き、価格も魅力的で、日常スナップ用に根強く使われている。$ja$ WHERE slug = 'c200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$英国Candido Collectiveのカラーネガ。Kodak Vision3 250Dのシネフィルムからリムジェットを除去して作っており、一般的なC-41ラボにそのまま出せる。デイライトバランスで昼の撮影に無難。$ja$ WHERE slug = 'candido400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$デイライトバランス。細かくクリーンな粒子と、日差しの下での自然な色合いが特徴。中国のOEM工場がKodak VISION3系の映画用フィルムを切り出し、リムジェットを除去して35mm 36枚撮りのパトローネに詰め直したライン。韓国では「チュンネスティル(中国版シネスティル)」の通称で知られる。正式なブランド名のない通称のため、色味や品質にはロットごとの差がある。DXコードがないためISOの手動設定が必須。一般的なC-41ラボで現像できる。$ja$ WHERE slug = 'chinesecinestill100d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$タングステンバランス。室内や舞台のように人工光源が主な場面で、落ち着いた色をとらえられる。中国のOEM工場がKodak VISION3系の映画用フィルムを切り出し、リムジェットを除去して35mm 36枚撮りのパトローネに詰め直したライン。韓国では「チュンネスティル(中国版シネスティル)」の通称で知られる。正式なブランド名のない通称のため、色味や品質にはロットごとの差がある。DXコードがないためISOの手動設定が必須。一般的なC-41ラボで現像できる。$ja$ WHERE slug = 'chinesecinestill320t' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$デイライトバランス。日差しの良い屋外から曇りの日まで無難にこなす万能のトーン。中国のOEM工場がKodak VISION3系の映画用フィルムを切り出し、リムジェットを除去して35mm 36枚撮りのパトローネに詰め直したライン。韓国では「チュンネスティル(中国版シネスティル)」の通称で知られる。正式なブランド名のない通称のため、色味や品質にはロットごとの差がある。DXコードがないためISOの手動設定が必須。一般的なC-41ラボで現像できる。$ja$ WHERE slug = 'chinesecinestill400d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$タングステンバランスの高感度。夜の街や都市の夜景のように人工光の多い低照度の現場で輝く。中国のOEM工場がKodak VISION3系の映画用フィルムを切り出し、リムジェットを除去して35mm 36枚撮りのパトローネに詰め直したライン。韓国では「チュンネスティル(中国版シネスティル)」の通称で知られる。正式なブランド名のない通称のため、色味や品質にはロットごとの差がある。DXコードがないためISOの手動設定が必須。一般的なC-41ラボで現像できる。$ja$ WHERE slug = 'chinesecinestill800t' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$2022年に発売されたCineStillの日常用フィルム。50Dより高感度で800Tより自然な色合いをもち、映画的なトーンを日常の風景に持ち込みたいときに選ぶ。$ja$ WHERE slug = 'cinestill400d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$CineStillがデイライト用の映画フィルムをカラーネガに仕立てたフィルム。ISO 50の低感度と豊かな色のディテールで、日差しの良い昼の風景に特によく合う。$ja$ WHERE slug = 'cinestill50d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$タングステン光源に合わせたシネマティックな色調と、ハイライトに出る強いハレーションが特徴。夜の街や都市の夜景によく映える。$ja$ WHERE slug = 'cinestill800t' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$CineStillのモノクロライン。Kodak Eastman Double-X 5222ベースで、粗い粒子と深いコントラストが映画的なムードを生む。一般のモノクロラボで処理できる。$ja$ WHERE slug = 'cinestillxx' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$最も手頃な価格帯のカラーフィルム。彩度が低く柔らかなトーンで、曇りの日や室内照明下でも意外なほど良い結果が出る。$ja$ WHERE slug = 'colorplus200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Deltaラインで最も細かく緻密な粒子。T粒子技術をベースに、風景、ポートレート、静物で滑らかなモノクロを求めるときによく選ばれる。富士フイルムAcros IIに近い立ち位置。$ja$ WHERE slug = 'delta100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$増感に対応したプロ用高感度モノクロ。実際のネイティブ感度はISO 1000〜1600ほどだが3200と表記された高感度ラインで、夜の街、コンサート、ドキュメンタリーなど低照度の現場によく登場する。$ja$ WHERE slug = 'delta3200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$DeltaシリーズはIlfordのT粒子(現代型の粒子)モノクロ。HP5より粒子が細かくトーンが緻密で、都市のスナップやポートレートでクリーンなモノクロを求めるときに選ぶ。$ja$ WHERE slug = 'delta400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kodakが映画撮影用に作ったモノクロのクラシック。5222というコード名のほうがよく知られ、深いコントラストと粗い粒状感が特徴。モノクロ映画の情緒を写真で生かしたいときに選ぶ。$ja$ WHERE slug = 'doublex' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$1999年に発売され2012年に生産終了したKodakのビビッドなリバーサルフィルム。ISO 100、E-6現像。名前のVSは「Vividly Saturated」の略で、自然、風景、料理のように強い色が似合う被写体に合わせて設計された。$ja$ WHERE slug = 'e100vs' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Lomographyの入門用モノクロ。Fomaベースとして知られ、細かな粒子と落ち着いたトーンで、日常のモノクロを始めるときに手に取りやすい。$ja$ WHERE slug = 'earlgrey100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kodakのリバーサルフィルム。2018年に復活したクラシックで、涼しげなトーンと素直な発色が特徴。スライド映写やフィルムスキャンのワークフローで今も根強く使われている。$ja$ WHERE slug = 'ektachrome100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kodak ProfessionalラインのISO 200リバーサルフィルム。増感(+1〜+3段)に強く、低照度、スタジオ、人工光の環境でよく使われた。落ち着いたトーンと細やかな粒状感が魅力だった。2012年に生産終了。$ja$ WHERE slug = 'ektachromeE200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kodak Professionalラインの高彩度カラーネガ。豊かな彩度と微粒子が特徴で、風景や旅行写真でリバーサルに近い発色を求めるときによく選ばれる。$ja$ WHERE slug = 'ektar100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムの映画用デイライト・カラーネガ。柔らかな発色と豊かなシャドーのディテールが特徴で、ドキュメンタリーやインディペンデント映画の撮影で長く使われた。Fujiが2018年に映画フィルム事業から撤退し、生産終了。$ja$ WHERE slug = 'eterna250d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムの映画用タングステン・カラーネガ。夜間や室内の撮影で高い感度と落ち着いた色を提供したが、2018年のFuji映画事業の終了とともに生産終了した。ヴィンテージ市場でときおり見かける。$ja$ WHERE slug = 'eterna500t' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$イタリアFerraniaの復活フィルム。1960年代のフェリーニ映画に使われたシネマフィルムの後継で、強いコントラスト、深い黒、銀の輝きが生きた微粒子が特徴。モノクロ映画のワンシーンのような雰囲気が出る。$ja$ WHERE slug = 'ferraniap30' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$マレーシアのFilmNeverDieが2018年に初めて出したカラーネガ。「色(イロ)」という名のとおり、オーストラリアとアジアの市場で一度すぐに完売したラインで、現在は生産終了だが、IROラインのアイデンティティを作った出発点。$ja$ WHERE slug = 'fndiro200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$IROシリーズの第2弾。1本39枚撮りで、彩度の生きたくっきりした色と柔らかな粒子により、自然光のスナップやストリート写真でよく名前が挙がる。C-41。$ja$ WHERE slug = 'fndiro400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$「キロ(黄色)」という名のとおり、トーンが温かい方向に傾いた27枚撮りのライン。IROの姉妹で、真昼の日差しをいっそう黄色く写すデイライトフィルム。C-41。$ja$ WHERE slug = 'fndkiro400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$「クモ(雲)」。Kodak Vision3 5207(250D)映画フィルムの原反をそのまま巻き直したECN-2のデイライトライン。リムジェット付きのためECN-2現像が正攻法で、真昼のシネマトーンに最も近づける方法。$ja$ WHERE slug = 'fndkumo250d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$「ソラ(空)」という名のとおり、デイライト光源によく応えるISO 200、36枚撮りのカラーネガ。爽やかなトーンと整った粒子が風景や旅行写真によく合う。C-41。$ja$ WHERE slug = 'fndsora200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$「ウミ(海)」という名のISO 800、36枚撮り。夜間や低照度に合わせ、青みがかったトーンと豊かなシャドーをとらえ、都市の夜景のルポルタージュでよく名前が挙がる。C-41。$ja$ WHERE slug = 'fndumi800' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$チェコFomaの低感度モノクロフィルム。ISO 100のクラシックな立方体結晶乳剤で、粗い粒状感と深いシャドーの描写が特徴。ヴィンテージなモノクロのムードを求めるときに強いライン。$ja$ WHERE slug = 'fomapan100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$チェコFomaのISO 200モノクロネガ。FOMAPAN 200 Creativeはパンクロマチックフィルムで、細かな粒子と高い解像力、シャープな輪郭描写を狙った中感度モノクロ。$ja$ WHERE slug = 'fomapan200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$チェコFomaのコストパフォーマンスに優れたモノクロ。HP5+やTri-Xより安く粒状感が粗く、ドキュメンタリーや実験的なモノクロによく合う。$ja$ WHERE slug = 'fomapan400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$韓国市場のシネマフィルム再巻きブランドFotocolaのデイライトライン。Kodak Vision3 250Dをベースにスチル写真用に仕立てており、C-41のラボでも処理できる。$ja$ WHERE slug = 'fotocola250d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Fotocolaのタングステンライン。Kodak Vision3 500Tベースのため、夜間や室内でシネマティックなトーンが出る。$ja$ WHERE slug = 'fotocola500t' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Ilfordの中感度モノクロ。豊かなグレートーンとクリーンな粒状感が特徴で、風景、静物、中判の作品に長く使われる正統派。$ja$ WHERE slug = 'fp4plus' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムのリバーサルラインで最も柔らかなトーンをもつポートレート用フィルム。自然な肌色と落ち着いた彩度で、ファッションやウェディングで長く使われた。2011年に生産終了。$ja$ WHERE slug = 'fujiastia100f' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムFujicolorラインのISO 100日常用カラーネガ。明るい昼間や旅行のスナップによく合う低感度フィルムで、澄んだ落ち着いた色と細かな粒状感が特徴。Fujifilm 200/400とともに基本のカラーラインとして選びやすい。$ja$ WHERE slug = 'fujifilm100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムの日常用カラーネガ200。シンプルな箱のデザインで再流通しているラインで、穏やかなコントラストとクリーンなトーンが特徴。日常のスナップに最も広く勧められるフィルム。$ja$ WHERE slug = 'fujifilm200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$2022年にシンプルな箱のラインで再発売された富士フイルムの日常用カラーネガ400。温かなトーン、自然な粒子、広いラチチュードで、晴れの日から曇りの日まで幅広く使える。Fujifilm 200/800と同じシリーズ。$ja$ WHERE slug = 'fujifilm400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムが1990年代に出した高感度モノクロフィルム。ISO 1600の粗い粒子と硬いコントラストで、夜間や室内の報道写真によく使われた。2010年前後に生産終了。$ja$ WHERE slug = 'fujineopan1600' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムの日常用モノクロフィルム。細かくクリーンな粒子で日本のモノクロ写真の情緒を作ったラインで、2013年に生産終了。Acros IIと並んで最もよく名前が挙がる日本のモノクロフィルム。$ja$ WHERE slug = 'fujineopan400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$1959年に発売され、日本のモノクロフィルムの標準になった日常用のロール。ISO 100の細かな粒子と寛容な露出ラチチュードで、写真館や学生の暗室で長く使われた。2009年前後に生産終了。$ja$ WHERE slug = 'fujineopanss' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムのプロ用カラーネガ。ポートレートやウェディング写真の定番だった柔らかなパステルトーンが特徴。2021年の生産終了発表後に価格が急騰し、ヴィンテージ・コレクター市場で最もよく話題にのぼるフィルム。$ja$ WHERE slug = 'fujipro400h' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムのかつての高感度カラーネガ。ISO 1600で、室内のパーティーや舞台のような暗い現場を一本に収められるよう作られたフィルム。現在は生産終了しており、出会うのは難しい。$ja$ WHERE slug = 'fujisuperhg1600' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Velvia 100とは別に発売された、一段落ち着いたリバーサル。彩度はVelvia 50と100の間で、トーンはより自然なため、風景のほか都市やポートレートにも使われた。2010年代半ばに生産終了。$ja$ WHERE slug = 'fujivelvia100f' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$温かな黄金色の色調で日常をノスタルジックに写すフィルム。価格のわりに結果が安定しており、フィルムを始めるときに最も多く選ばれる一本。$ja$ WHERE slug = 'gold200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$中国・上海フィルムの最も歴史あるモノクロライン。粗い粒子と硬いコントラストが都市風景やドキュメンタリーによく使われ、生産終了と再発売を繰り返してきた中国モノクロのクラシック。$ja$ WHERE slug = 'gp3100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$GP3シリーズの高感度の兄弟。ISO 400の粗い粒子が夜間や室内のルポルタージュによく使われ、増感にも寛容なほう。$ja$ WHERE slug = 'gp3400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Holgaカメラ向けにブランディングされたISO 400のパンクロマチック・モノクロネガ。Fomaが供給するフィルムとして知られ、粗い粒子と淡泊なトーンがトイカメラのゆるい描写によく合う。$ja$ WHERE slug = 'holga400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$現像ラチチュードが広くグレートーンが豊かなモノクロフィルムの定番。ドキュメンタリーやストリート写真でまず思い浮かぶフィルム。$ja$ WHERE slug = 'hp5plus' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$モノクロでおなじみのIlfordの名を冠したカラーネガ。現在はIlfocolor Vintage Tone 400 Plusの名で販売されている。色がややシアン寄りに傾き、緑と青は沈み、赤と黄が際立つため、名前のとおり古い写真のような色が出るという説明が添えられている。C-41現像、デイライトバランス、35mm 24枚撮り・36枚撮り。$ja$ WHERE slug = 'ilfocolor400plus' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Ilfordの学生向け・低価格ラインのモノクロ。Kentmere Panと同じ工場で生産され、柔らかなトーンと適度なコントラスト、大きめの粒子が特徴。手頃な価格で、モノクロを始めるときに勧めたいフィルム。$ja$ WHERE slug = 'ilfordpan100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムの日本向け業務用ラインのISO 100。Pro Image 100に近い立ち位置で、安定した保存性と温かな色合いが特徴。$ja$ WHERE slug = 'industrial100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$業務用ラインのISO 400。Pro 400Hのいとこのような存在で、日本の業務撮影やポートレートに幅広く使われた。日本限定の流通。$ja$ WHERE slug = 'industrial400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Japan Camera Hunterが発売した自社ブランドのモノクロフィルム。強いコントラスト、粗い粒子、赤への感色性の拡張が特徴で、ストリート写真のカルト的なラインになった。$ja$ WHERE slug = 'jchstreetpan400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kentmereの入門用ISO 100モノクロ。Ilford Delta 100やFP4より安いながら細かく落ち着いた粒状感で、モノクロの風景や静物の入門用によく勧められる。$ja$ WHERE slug = 'kentmere100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$2024年に発売されたKentmereの新しい乳剤。Pan 100とPan 400の間の中感度で、風景、日常、ポートレートを無難にこなすバランス型のモノクロフィルム。$ja$ WHERE slug = 'kentmere200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Ilford傘下のラインとして知られる入門用モノクロフィルム。HP5やDeltaより安いが結果は十分に安定しており、初めてモノクロを使う人に勧めたいフィルム。$ja$ WHERE slug = 'kentmere400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kodakが再び出した低感度のデイライト用カラーネガ。Pro Image 100系にごく近い自然な色味で知られるが、やや落ち着いたニュートラルな印象のため、別のフィルムとして扱うのが無難。$ja$ WHERE slug = 'kodacolor100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$中感度の日常用カラーネガ。Gold 200とは性格が異なり、ColorPlus 200系に近い柔らかく気軽な色を見せるフィルムと考えるのがよい。$ja$ WHERE slug = 'kodacolor200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kodakの映画撮影用カラーリバーサルフィルム。35mmシネのカタログコード5294で出荷される、デイライトバランスISO 100のE-6リバーサル。自然光や屋外の撮影で深い彩度と細かな粒状感が特徴で、短編映画やミュージックビデオなどでときおり登場するシネストック。$ja$ WHERE slug = 'kodake100d5294' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Konicaの一般的なISO 100カラーネガ。Centuriaラインで最も細かな粒子で、風景や旅行写真によく使われた。2006年頃に生産終了。$ja$ WHERE slug = 'konicacenturia100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Konica Centuriaラインの中感度。温かな色合いとバランスの取れたコントラストで、日常写真に長く使われた。2006年に生産終了。$ja$ WHERE slug = 'konicacenturia200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Konicaの日常用カラーネガのライン。2000年代には韓国の写真家にとってコストパフォーマンスの良い選択肢として長く使われたが、Konicaが写真事業から撤退し、2006年頃に生産終了した。$ja$ WHERE slug = 'konicacenturia400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$日本で業務用として流通していたコニカのISO 100カラーネガ。ニュートラルに近い発色と端正な粒状感が特徴で、推奨EIが50〜80の間でもよく写り、ラチチュードに余裕があるという評価。生産終了。$ja$ WHERE slug = 'konicaindustrial100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Earl GreyのISO 400の姉妹。粗い粒子と深いコントラストで、街角やポートレートのモノクロによく合う。$ja$ WHERE slug = 'ladygrey400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$2025年に発売されたLomographyの温かなトーンのカラーネガ。自然な肌色とクラシックなアナログのルックを目指しており、日常の写真によく合う。ISO 200、C-41標準現像。$ja$ WHERE slug = 'lomoclassicolor200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Lomographyの粒子の細かい日常用カラー。日差しの強い屋外で発色が安定しており、入門用としてもよく勧められる。$ja$ WHERE slug = 'lomocolor100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Lomographyブランドの日常用カラーフィルム。自社生産ではなく時期によってベースフィルムが変わるため仕上がりにばらつきがあるが、その予測のつかなさがかえってロモらしさとして受け取られている。$ja$ WHERE slug = 'lomocolor400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Lomographyの高感度日常用カラー。室内や日没後の風景に強く、粗い粒状感があえて味になるフィルム。$ja$ WHERE slug = 'lomocolor800' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$2023年発売。90年代の映画のトーンの再現を狙ったカラーネガで、豊かなグレイン、深いブルー、鮮やかなレッド、澄んだイエローが特徴。C-41の標準現像で、パトローネにDXコードが印刷されていないためISOを手動で設定する必要がある。$ja$ WHERE slug = 'lomocolor92' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$彩度を抑えコントラストを引き上げた、都市のムードのカラーフィルム。コロナ禍のグレーがかった都市風景によく合い、一気に人気を集めた。$ja$ WHERE slug = 'lomometropolis' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$緑を紫に、青を青緑に変えるカラーシフトフィルム。C-41で現像でき、非現実的で幻想的な仕上がりになるため実験的な写真によく登場する。$ja$ WHERE slug = 'lomopurple' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Lomographyのレッドスケール・カラーフィルム。一般的なカラーフィルムの裏側から露光させる方式で、赤と黄のトーンが強く出る。ISO 50〜200の範囲で露光を選べる。$ja$ WHERE slug = 'lomoredscale' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$感度と露出に応じて強い青緑のトーンに色がシフトするカラーネガ。PurpleやMetropolisと並ぶLomoChromeシリーズの一員で、ISO 100〜400の範囲で自由に露出できる。$ja$ WHERE slug = 'lomoturquoise' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$2012年に生産終了した中国Luckyのカラーネガが、2025年前半に復活した最初のカラーライン。ISO 200、C-41標準現像。ニュートラルなトーンにわずかな赤かぶり、細かな粒子とパンチのあるコントラストが特徴。35mmと120の両方で発売。$ja$ WHERE slug = 'luckycolor200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$中国・河北のLucky Group Corporationが作る低価格の35mmモノクロフィルム。2017年に改良されたNew版は柔らかなトーンが特徴で、ハレーション防止層が弱いためハイライトの周りに淡いグローが出るのが独特の印象を生む。Kodak D-76での標準現像。$ja$ WHERE slug = 'luckyshd100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$中国LuckyのISO 400モノクロフィルム。2000年代初めにKodakとの協力で生産され、2012年に生産終了したラインが2024年3月に復活した。広い露出ラチチュードと粒子のディテールが特徴で、屋外でもスタジオでも扱いやすい。D-76標準現像、EI 200でやや控えめにレーティングするのが推奨。$ja$ WHERE slug = 'luckyshd400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$ライカが2025年に出した初のモノクロフィルム。ISO 50、280 lp/mmの超高解像度と780nmまでのスーパーパンクロマチック感光性が特徴。日差しの良い日に大口径レンズと組み合わせたとき、本領を発揮する。$ja$ WHERE slug = 'monopan50' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムのISO 1600高感度カラーフィルム。日本限定の発売で、低照度や室内のポートレートに強く、生産終了後にコレクター市場で価格が大きく上がったカルトフィルム。$ja$ WHERE slug = 'natura1600' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$ドイツのInovisCoatがコーティングするC-41カラーネガ。Wolfen NC200の乳剤を使う。同じNC系のNC400やNC500と違ってオレンジベースのため、スキャンがしやすい。自然な色とくっきりしたコントラストが特徴で、緑と赤がよく出るという評価がつきまとう。肌色はやや温かい側なので、ポートレートにも無難。デイライトバランス、35mm 36枚撮り。$ja$ WHERE slug = 'opticolour200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Harman(Ilfordと同じ英国の工場)が日本市場向けに作るモノクロ。2016年にISO 400とともに発売され、入門・学生向けラインとして手頃な価格が特徴。英国生産、日本流通。$ja$ WHERE slug = 'orientalseagull100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Harman(Ilfordと同じ英国の工場)が日本市場向けに作るモノクロの高感度ライン。2016年にISO 100とともに発売された入門・学生向けラインの400版で、感度が一段上がったぶん室内や低照度でも気兼ねなくシャッターを切れる。英国生産、日本流通。$ja$ WHERE slug = 'orientalseagull400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$赤に感光しないオルソクロマチックのモノクロフィルム。ポートレートでは唇や肌色が暗く落ちるが、静物、風景、複写では深い青空と硬質なトーンが出る。暗室で赤いセーフライトの下で扱えるのも利点。$ja$ WHERE slug = 'orthoplus80' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$ドイツORWOのISO 400モノクロフィルム。東ドイツ時代のNP15系の後継ラインで、重厚なコントラストと粗い粒子が特徴。ドキュメンタリーやストリートで強い印象を残したいときによく合う。$ja$ WHERE slug = 'orwon75' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$ORWOのISO 100モノクロ・シネマフィルム。微粒子、豊かなグレーのグラデーション、クリーンなトーンが特徴で、映画のように滑らかなモノクロを求めるときに良い選択。Berlin KinoとPotsdam Kinoのベースフィルムでもある。$ja$ WHERE slug = 'orwoun54' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Ilfordで最も低感度のモノクロフィルム。ISO 50の低感度が生む極めて細かく緻密な粒状感と豊かなトーンのグラデーションが特徴で、日差しの強い風景、静物、複写に最適。$ja$ WHERE slug = 'panfplus50' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$2024年に発売されたPhoenixの改良第2世代。第1世代ならではの強烈なグレインと赤いトーンはそのままに、ラチチュードが広がって扱いやすくなった。Ilfordの工場で作られる英国製カラーネガとして唯一のラインナップ。$ja$ WHERE slug = 'phoenix2' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$モノクロメーカーのHarmanが2023年に出した初のカラーフィルム。強いコントラスト、赤みのあるベース、粗い粒子が特徴で、「実験的な色」を狙うときに真っ先に浮かぶフィルム。$ja$ WHERE slug = 'phoenix200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Portraファミリーで最も柔らかなトーン。彩度が低くディテールが豊かで、自然光のポートレートやウェディング写真の定番になった。日差しの強い屋外で特によく映える。$ja$ WHERE slug = 'portra160' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$1998年に発売されたPortra第1世代のNatural Colorライン。彩度が低く柔らかな肌色が特徴で、ウェディングやポートレートの定番として使われた。2010年に生産終了し、現行のPortraラインに統合。$ja$ WHERE slug = 'portra160nc' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Portra第1世代のVivid Colorライン。NCより彩度が高く鮮やかな発色が特徴で、広告やファッションの撮影でよく選ばれた。2010年に生産終了。$ja$ WHERE slug = 'portra160vc' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$プロ用カラーネガの代名詞。柔らかな肌色と広いラチチュードで、ポートレート、ウェディング、ドキュメンタリーの定番になったフィルム。$ja$ WHERE slug = 'portra400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Portra第1世代のISO 400 Natural Color。ポートレートやウェディングの標準カラーとして最もよく挙げられたライン。2010年に生産終了し、現行のPortra 400に統合。$ja$ WHERE slug = 'portra400nc' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Portra 400のVivid Colorバリエーション。より強い彩度で、日常で濃い色を求めるときに選ばれた。2010年に生産終了。$ja$ WHERE slug = 'portra400vc' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Portraシリーズで最も高感度。室内や夕暮れ時のポートレートでまず手に取るフィルム。粒子は粗めだが、色はPortraらしく柔らかいまま。$ja$ WHERE slug = 'portra800' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$ORWOのシネマフィルムをベースにした低感度モノクロ。微細な粒子と柔らかな中間調が特徴で、風景や静物でクラシック映画のようなディテールをとらえる。$ja$ WHERE slug = 'potsdamkino100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kodak ProImage 100の兄弟ラインとして、メキシコ、中南米、アジアの一部の市場で流通していたカラーネガ。ウェディングやポートレート用に勧められるラインで、Portraの代替としてよく名前が挙がった。現在は生産終了。$ja$ WHERE slug = 'profotoxl100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kodakが高温多湿な地域の市場向けに作ったカラーネガ。保存安定性が高く温かなトーンが魅力で、コストパフォーマンスの良い日常・旅行用フィルムとして知られる。$ja$ WHERE slug = 'proimage100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムのリバーサルフィルムの中で最も自然な発色とされるライン。Velviaより彩度が低く、ポートレートや都市のスナップでも気負わず使える。$ja$ WHERE slug = 'provia100f' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムが1990年代後半に発売したカラーネガ。一般的なカラーフィルムのRGB 3層に加えて4番目のシアン感光層を設け、人工照明下でも正確な色をとらえたのが特徴だった。2013年に生産終了。ヴィンテージ市場では今も取引されている。$ja$ WHERE slug = 'reala100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムが映画撮影用に作ったデイライトのカラーネガ。ISO 500の高感度と第4の感色層の技術で、複雑なミックス光でも色再現を安定してとらえるのが特徴。正式な処理はECN-2で、現在は生産終了したヴィンテージのシネマストック。$ja$ WHERE slug = 'reala500d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$2024年に韓国・日本市場限定で発売された富士フイルムの新しいプロ用カラーネガ100。初代Realaの第4の感色層の構造を受け継ぐラインで、豊かな色再現、柔らかなトーン、微粒子が特徴。ポートレートや静物に勧めたい貴重なフィルム。$ja$ WHERE slug = 'realaace100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Vision3 5207のリムジェットだけを除去し、ネイティブのISO 250のまま詰め直したライン。増感しないぶん粒子が整い、ハイライトが生きるため、自然光のポートレートや日常によく合うデイライトフィルム。C-41。$ja$ WHERE slug = 'reflxlab250d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kodakが新たに出したAHU(anti-halation undercoat)処理の5207を、ISO 320として詰め直したもの。リムジェットもハレーションもなく、Portra 400に近い質感をC-41で得られる。$ja$ WHERE slug = 'reflxlab320d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Vision3 5207(250D)のリムジェットを除去し、一段増感する前提でISO 400のデイライトとして詰め直したライン。残るハレーションが光のあふれる真昼を柔らかく包む。C-41。$ja$ WHERE slug = 'reflxlab400d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$深圳のReflx LabがKodak Vision3 5219(500T)のリムジェットを除去し、ISO 800に増感する前提で巻き直したフィルム。夜の街やタングステン光源でシネマトーンに最も安く出会える方法としてよく名前が挙がる。C-41。$ja$ WHERE slug = 'reflxlab800t' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Glowの姉妹。同じ27枚撮りの短いロールで、青みがかった冷たいトーンと粗いグレインにより、光の強い真昼を冷ややかに写す。C-41。$ja$ WHERE slug = 'retoaqua400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$香港のRetoが2023年に出したISO 400カラーネガ。27枚撮りの短いロールで、色あせた温かなトーンと低いコントラストで都市の午後をシネマトーンに写す。C-41。$ja$ WHERE slug = 'retoglow400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Retoのラインナップで最もくっきりしたライン。36枚撮り、微細な粒子に中〜高めのコントラスト、生きた彩度で、ヴィンテージというよりはっきりした日常の色味を与える。C-41。$ja$ WHERE slug = 'retoprism400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Retro 80SのISO 400の姉妹。拡張したIR感光性に高い感度を組み合わせたラインで、ストリートや旅行写真で手早くIR効果を得たいときに使う。$ja$ WHERE slug = 'rolleiretro400s' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Rolleiの赤外域まで感光域を広げたモノクロ。720nmのIRフィルターと組み合わせると、葉が白く空が黒くなるIRルックになる。豊かなトーンと微粒子。$ja$ WHERE slug = 'rolleiretro80s' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Rolleiの伝統的なモノクロライン。クラシックな粒子と柔らかなトーンのグラデーションが、正統派のモノクロのムードによく合う。$ja$ WHERE slug = 'rpx100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$RPXラインのISO 400。粗い粒子と強いコントラストがドキュメンタリーやストリートによく合い、HP5+のヨーロッパ製の代替としてよく名前が挙がる。$ja$ WHERE slug = 'rpx400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$赤から近赤外まで感光域を広げたモノクロフィルム。720nmの赤外フィルターと組み合わせると、葉が白く空が黒くなるIRルックになる。一般のモノクロラボで処理できる特殊フィルム。$ja$ WHERE slug = 'sfx200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Fujiらしい青緑と緑の描写が生きた日常用カラーフィルム。Kodak系の温かみとは違う涼しげなトーンが好きなら、何度も手が伸びる一本。$ja$ WHERE slug = 'superia400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムの日本市場向けプレミアムライン。Superia 400の一族だが、一段洗練された発色と細かな粒子が特徴で、ポートレートや日常写真に長く使われた。2024年に生産終了。$ja$ WHERE slug = 'superiapremium400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$日本市場限定で発売されていた富士フイルムの高感度カラーフィルム。柔らかな肌色の描写でポートレートに厚いファン層を築いたラインで、生産終了後もヴィンテージ市場でよく話題にのぼる。$ja$ WHERE slug = 'superiavenus800' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$T-Max 400の低感度の姉妹。ISO 100ならではの最も細かく緻密な粒状感で、ファッション、静物、大判プリントに強いモノクロフィルム。Tri-Xの粗い質感とは正反対の方向。$ja$ WHERE slug = 'tmax100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$T-MaxはKodakの現代的なモノクロライン。Tri-Xより粒子が細かくトーンが滑らかで、緻密なモノクロを求めるときに選ぶ。ファッション、静物、風景で幅広く使われる。$ja$ WHERE slug = 'tmax400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kodakの高感度モノクロ。実際のネイティブ感度は800〜1000ほどだが、P3200まで増感できるよう設計されている。2012年に生産終了し、2018年に復活したライン。$ja$ WHERE slug = 'tmaxp3200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$写真史に刻まれたモノクロフィルムの象徴。粗い粒子と深いコントラストで、報道写真やドキュメンタリーのトーンを作ってきたフィルム。$ja$ WHERE slug = 'trix400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$英国Tudor Photographyの低価格カラーネガ。日本の富士フイルム製のリブランドとして知られ、C-41で現像する。気負わずどんどん撮れる日常用カラーフィルム。$ja$ WHERE slug = 'tudorxlx100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$英国Tudor Photographyの低価格カラーネガ。日本の富士フイルム製のリブランドとして知られ、C-41で現像する。気負わずどんどん撮れる日常用カラーフィルム。$ja$ WHERE slug = 'tudorxlx200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$日常用カラーフィルムの代表格。豊かな彩度と柔らかな粒状感で、日々の光景を温かく写す。日差しの下で特によく映える。$ja$ WHERE slug = 'ultramax' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Velvia 50より一段高感度な姉妹フィルム。濃い彩度はそのままに、ISO 100で手持ち撮影もぐっと楽になり、風景のほか街角やポートレートにもよく使われる。$ja$ WHERE slug = 'velvia100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムのリバーサルフィルムの代表。極めて彩度の高い緑と赤の描写で、風景写真の伝説になったフィルム。ISO 50の低感度のため三脚はほぼ必須。$ja$ WHERE slug = 'velvia50' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kodakが現在量産している映画用カラーネガのデイライトバランスのライン。正式な処理はECN-2で、リムジェットのバッキングが残っているため、豊かなディテールと正確な映画的トーンが出る。$ja$ WHERE slug = 'vision250d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Vision3 250Dをスチル写真用に仕立てたバージョン。AHU(anti-halation undercoat)のバッキングをそのまま残しているためハレーションが穏やかで、トーンは映画のように深い。一部のラボがC-41でも処理してくれる点が強み。$ja$ WHERE slug = 'vision250dahu' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$ハリウッドの映画撮影現場で標準のタングステン200T。ECN-2現像が正攻法だが、リムジェットを除去すればC-41でも使え、夜の街の光をシネマトーンに写し取ってきたライン。CineStill 200Tはこのフィルムを詰め替えたC-41版。$ja$ WHERE slug = 'vision3200t' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kodakの映画用タングステン・カラーネガ。ISO 500の高感度で夜の街や室内撮影の定番として使われ、ECN-2処理が基本。CineStill 800Tの元になったフィルムとも呼ばれる。$ja$ WHERE slug = 'vision500t' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Vision3 500Tのスチル用バージョン。タングステン照明に強く、ハレーションを抑えた夜の映画的なトーンが特徴。CineStill 800Tの強い赤のハレーションと比べると、ひときわ落ち着いた映画のムード。$ja$ WHERE slug = 'vision500tahu' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$NC500の姉妹。同じ東ドイツの映画用乳剤の系譜で一段感度を下げた、ISO 400のカラーネガ。粗い粒子と豊かなトーンで、自然光のストリート写真によく名前が挙がる。$ja$ WHERE slug = 'wolfennc400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$2023年に復活したORWOのカラーネガ・シネマフィルム。映画的な青緑のシャドーと温かなハイライトが印象的。本来はECN-2処理が推奨だが一般的なC-41現像もでき、シネルックを日常の写真に持ち込みたいときに向く。$ja$ WHERE slug = 'wolfennc500' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$モノクロフィルムでありながらC-41(カラー)方式で現像する珍しいフィルム。一般のカラーラボで処理できるため、モノクロを始める敷居を大きく下げてくれる。$ja$ WHERE slug = 'xp2super' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Yashica MF-1ラインのモノクロISO 400。強いコントラストでストリートスナップに似合うという評価がある。$ja$ WHERE slug = 'yashicabw400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$YashicaがMF-1カメラとともに再び送り出したISO 400カラーネガ。温かく傾くトーンと柔らかな粒子が、ポートレートや日常スナップによく合う。C-41。$ja$ WHERE slug = 'yashicacolor400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Yashicaの限定版カラーISO 400。80年代の雰囲気を狙って彩度を大きく引き上げたトーンと強い粒子で、自然光の日常スナップによく登場する。C-41。$ja$ WHERE slug = 'yashicagolden80s' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$マレーシアのFilmNeverDieが写真家Mr. Negativeとコラボレーションした、ISO 400のカラーネガ。彩度を抜いて粒子をくっきり生かした「色あせたホラー」ルックで、日本や東南アジアのコレクターに人気のライン。C-41。$ja$ WHERE slug = 'zombie400' AND description_ja IS NULL;

