UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$落星垈写真館$ja$), address_ja = COALESCE(address_ja, $ja$ソウル特別市 冠岳区 奉天路 582 2階$ja$), features_ja = COALESCE(features_ja, NULL) WHERE name = '낙성대사진관' AND region = '서울';
