UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$タレバダ$ja$), address_ja = COALESCE(address_ja, $ja$京畿道 富川市 遠美区 チャンマル路 173 地階$ja$), features_ja = COALESCE(features_ja, $ja$写真スタジオ兼現像所。
