UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$マンウサムリム$ja$), address_ja = COALESCE(address_ja, $ja$ソウル特別市 中区 乙支路 108 3階・4階$ja$), features_ja = COALESCE(features_ja, NULL) WHERE name = '망우삼림' AND region = '서울';
