UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$ミリム写真館$ja$), address_ja = COALESCE(address_ja, $ja$ソウル特別市 広津区 クァンナル路24ギル 21 1階(建国大学校 旧正門前)$ja$), features_ja = COALESCE(features_ja, $ja$現金払いと口座振込なら高画質でスキャン。$ja$) WHERE name = '미림사진관' AND region = '서울';
UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$ボダボム$ja$), address_ja = COALESCE(address_ja, $ja$ソウル特別市 中区 水標路 1 ソフィアハウスビル 4階$ja$), features_ja = COALESCE(features_ja, $ja$Imacon X5のドラムスキャン、モノクロ専用液での現像、プレミアム現像、ベタ焼きに対応。$ja$) WHERE name = '보다봄' AND region = '서울';
UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$プグァン写真館$ja$), address_ja = COALESCE(address_ja, $ja$蔚山広域市 南区 ワンセン路66番ギル 30 1階$ja$), features_ja = COALESCE(features_ja, $ja$フィルム現像・スキャン(現像のみ、スキャンのみも個別に可)。証明写真スタジオを兼業。$ja$) WHERE name = '부광사진관' AND region = '울산';
UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$セハフォトラボ$ja$), address_ja = COALESCE(address_ja, $ja$大邱広域市 北区 八達路35ギル 4 3階$ja$), features_ja = COALESCE(features_ja, $ja$C-41・ECN-2・モノクロフィルムの現像とスキャン。高解像度スキャンは5,000ウォン追加。120のモノクロはTIFFでスキャン。$ja$) WHERE name = '세하포토랩' AND region = '대구';
UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$Scopy 弘大$ja$), address_ja = COALESCE(address_ja, $ja$ソウル特別市 麻浦区 楊花路18アンギル 17 弘益ビル 2階$ja$), features_ja = COALESCE(features_ja, NULL) WHERE name = '스코피 홍대' AND region = '서울';
UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$Scopy 鷺梁津$ja$), address_ja = COALESCE(address_ja, $ja$ソウル特別市 銅雀区 チャンスンベギ路 164$ja$), features_ja = COALESCE(features_ja, NULL) WHERE name = '스코피 노량진' AND region = '서울';
UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$シンシンカラー$ja$), address_ja = COALESCE(address_ja, $ja$ソウル特別市 江南区 論峴路151ギル 10$ja$), features_ja = COALESCE(features_ja, $ja$ノーリツとフジのスキャナーを選べる。$ja$) WHERE name = '신신칼라' AND region = '서울';
UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$AT写真館$ja$), address_ja = COALESCE(address_ja, $ja$蔚山広域市 中区 セジュムネコリ 40$ja$), features_ja = COALESCE(features_ja, $ja$モノクロフィルム現像、湿板写真(予約制)。証明写真スタジオを兼業。$ja$) WHERE name = '에이티사진관' AND region = '울산';
UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$エリーカメラ$ja$), address_ja = COALESCE(address_ja, $ja$ソウル特別市 麻浦区 ソンアム路 28 105号$ja$), features_ja = COALESCE(features_ja, $ja$フィルムカメラの専門店で、店舗兼現像所。$ja$) WHERE name = '엘리카메라' AND region = '서울';
UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$延南フィルム$ja$), address_ja = COALESCE(address_ja, $ja$ソウル特別市 麻浦区 ソンミサン路29アンギル 11 右側202号(延南洞)$ja$), features_ja = COALESCE(features_ja, $ja$2026年7月10日に価格が変わった。訪れる前にホームページで確かめておくのが無難。$ja$) WHERE name = '연남 필름' AND region = '서울';
UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$オクサンフィルム$ja$), address_ja = COALESCE(address_ja, $ja$ソウル特別市 中区 東湖路 349 4階$ja$), features_ja = COALESCE(features_ja, $ja$カラー・モノクロ・リバーサル・映画用(ECN-2)の現像とスキャン。画質は標準と高解像度から選べる。中判フィルムは扱わない。$ja$) WHERE name = '옥상필름' AND region = '서울';
UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$ウソン商事$ja$), address_ja = COALESCE(address_ja, $ja$ソウル特別市 鍾路区 敦化門路 31$ja$), features_ja = COALESCE(features_ja, NULL) WHERE name = '우성상사' AND region = '서울';
UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$ウィークエンドフィルム$ja$), address_ja = COALESCE(address_ja, $ja$ソウル特別市 城北区 昌慶宮路43ギル 36 1階$ja$), features_ja = COALESCE(features_ja, NULL) WHERE name = '위켄드 필름' AND region = '서울';
