UPDATE public.repair_shops SET name_ja = COALESCE(name_ja, $ja$名門カメラ$ja$), address_ja = COALESCE(address_ja, $ja$大邱広域市 北区 流通団地路 45 電子館 1階 299号$ja$), specialty_ja = COALESCE(specialty_ja, NULL), description_ja = COALESCE(description_ja, $ja$大邱の電子館の中にある。地元で口コミを頼りに訪ねる人が多いカメラ店。$ja$) WHERE name = '명문카메라' AND region = '대구';
UPDATE public.repair_shops SET name_ja = COALESCE(name_ja, $ja$ユソンカメラ$ja$), address_ja = COALESCE(address_ja, $ja$大邱広域市 中区 国債報償路 580 テヒョンフリーモール E-31$ja$), specialty_ja = COALESCE(specialty_ja, $ja$簡単な整備$ja$), description_ja = COALESCE(description_ja, $ja$大邱の中央路の地下商店街にある。簡単な整備は丁寧に見てくれ、大邱圏では名の知られた店。$ja$) WHERE name = '유성카메라' AND region = '대구';
UPDATE public.repair_shops SET name_ja = COALESCE(name_ja, $ja$中央カメラ$ja$), address_ja = COALESCE(address_ja, $ja$釜山広域市 中区 中区路43番ギル 8 ミジンアーケード内$ja$), specialty_ja = COALESCE(specialty_ja, $ja$フィルム・デジタルカメラの修理$ja$), description_ja = COALESCE(description_ja, $ja$富平カントン市場のミジンアーケードの奥にある。国際市場2・3工区の入口の向かい。フィルムカメラとデジタルカメラの両方を修理し、カメラの小売りもしている。店内が狭く、修理に集中しているときは対応が遅れることがあるので、時間に余裕をもって行くのがよい。行く前に修理できるかどうかと部品の在庫を尋ねておくことを勧める。$ja$) WHERE name = '중앙카메라' AND region = '부산';
UPDATE public.repair_shops SET name_ja = COALESCE(name_ja, $ja$チャルカギサンジャ$ja$), address_ja = COALESCE(address_ja, $ja$釜山広域市 海雲台区 チェソン1路 23 2階$ja$), specialty_ja = COALESCE(specialty_ja, $ja$マニュアルのフィルムカメラ、レンジファインダー、レンズ$ja$), description_ja = COALESCE(description_ja, $ja$海雲台の栽松洞にある。主にマニュアルのフィルムカメラを扱う。ニコンF・FM・FE、キヤノンAシリーズとキャノネット、ペンタックスSP・K・M、ミノルタX300とSRT、オリンパスPENとトリップ35、ヤシカ エレクトロをはじめ、リコー・マミヤ・コニカ・フジカ・プラクチカ・コンタックス・トプコンまで、扱う機種の一覧を公開している。点検と分解清掃からオーバーホールまで行う。レンズの清掃と絞り・ピントの調整も引き受ける。コシナCT-1、コビカ35、ヤシカFX-3、リコーXR-5のようなマイナーブランドのマニュアル機は修理代を割り引いてくれる。公開されている機種一覧と料金表は2021年4月時点のもので、現在とは異なる場合がある。行く前に修理の可否と費用を尋ねておくのがよい。$ja$) WHERE name = '찰칵이상자' AND region = '부산';

-- ── 관리 화면에서만 등록했거나 이름을 바꿔 저장소 사본과 달라진 행 (20261001000002 와 같은 행) ──

-- 필름 31종
UPDATE public.films SET description_ja = $ja$マイクロフィルムの乳剤を写真用に仕立てた、Adoxの超低感度モノクロフィルム。単分散乳剤により粒子がほぼ消えるほどの解像力を発揮し、大判プリントや複写でよく選ばれる。本来の性能を引き出すには専用現像液Adotech II/IIIとの組み合わせが前提。$ja$ WHERE slug = 'adoxcms20' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$AdoxのSilvermaxをベースにリバーサル現像で仕上げるモノクロリバーサルフィルム。デイライトでISO 160、ネガとしてISO 80〜100でも使える。透明なトリアセテートベースにハレーション防止層付き。Silvermaxの生産終了により供給は限られる。$ja$ WHERE slug = 'adoxscala160' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$AdoxのHR-50をベースにリバーサル現像で仕上げるモノクロリバーサルフィルム。超微粒子、透明なベース、スーパーパンクロマチックの感色性で映写に向く。dr5などのリバーサル専門ラボか、家庭用リバーサルキットで処理する。35mm 36枚撮り。$ja$ WHERE slug = 'adoxscala50' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$銀を多く含む伝統的なモノクロネガで、広い露出ラチチュードと豊かな階調で知られる。Adox Scala 160のベースでもあり、現在は生産終了または供給が限られている。残った在庫が出たときに一本ずつ見かける程度。$ja$ WHERE slug = 'adoxsilvermax100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$auroer film 400は韓国のブランドAuroerの35mmカラーフィルム。日常のスナップ、旅行、気軽な記録向けのISO 400フィルムで、フィルムカメラを始めたばかりの人でも安心して使えるように作られている。$ja$ WHERE slug = 'auroer400d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$auroer 800TはAuroerのISO 800タングステン・カラーフィルム。35mm 36枚撮りで、一般のカラーラボでC-41現像できるシネマフィルムとして販売されている。夜、室内、ネオンやタングステン光のように色温度の低い場面で真価を発揮し、仕上がりは温かな黄色よりもクールでシネマティックなトーンに寄る。$ja$ WHERE slug = 'auroer800t' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$チェコFomaのモノクロリバーサルフィルム。生産終了したAgfa Scalaに最も近い代替としてよく名前が挙がり、35mm 36枚撮りのほか8mmとSuper 16mmのシネ用フォーマットもある。専用のR-100リバーサル処理が必要で、通常のネガ現像には出せない。$ja$ WHERE slug = 'fomapanr100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムが1990年代に韓国市場のコンパクトカメラ向けに出したISO 200カラーネガ。箱の表記が韓国語のみの韓国限定ラインで、現在は生産終了。$ja$ WHERE slug = 'fujiototo200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$映画の後処理で複製に使う中間用のストック。オリジナルのカメラネガからマスターポジを焼くためのもので、感度は極めて低い。KodakはISOを公表しておらず、135に詰め替えて売る販売店はEI 0.8〜3を勧めている。タングステンバランスで本来の処理はECN-2。2242はESTARベースのためリムジェットはない。三脚と明るい光はほぼ必須。$ja$ WHERE slug = 'kodak2242' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$1986年にKodacolor VR-G 100として登場し、1989年にKodacolor Gold 100、1997年にKodak Gold 100と改名されながら、Kodakの一般向けカラーラインを担った。2000年代初めに生産終了し、現在は冷凍保存品が残るのみ。35mmと120の両方で発売された。$ja$ WHERE slug = 'kodakgold100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$KodakのレンズつきフィルムFunSaverに入っているISO 800カラーネガ。Goldファミリーに属し、単体のロールとしても販売されてきた。800にしては粒子が細かく、室内や夜のフラッシュ撮影によく合う。標準のC-41処理。$ja$ WHERE slug = 'kodakgt800' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$ハリウッドの映画撮影現場で標準の50Dデイライトストック。ECN-2が正攻法だが、リムジェットを除去すればC-41にも出せる。$ja$ WHERE slug = 'kodakvision350d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$中国LuckyのISO 400カラーネガ。標準のC-41処理、35mm 36枚撮り。同じラインのColor 200の高感度版。Kodakより彩度が低くややクール寄りで、シネマティックと評される。400らしく粒子は見えるが、均一に乗り、Fuji Superiaに近い。$ja$ WHERE slug = 'luckyxolor400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$日本のMARIXが2021年から詰め替えているシネフィルム。Kodak Vision3 50D(5203)のリムジェットを除去し、どのC-41ラボでも現像できるロールに仕立てている。ベースはISO 50の映画用フィルムだが、リムジェット除去後の推奨感度はISO 100。真昼の日差しに軽くシネマトーンを添える入門用の選択肢。$ja$ WHERE slug = 'marix100d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kodak Vision3 250D(5207)からリムジェットを除去したもの。C-41で現像できるため街の写真店でもこのシネフィルムを受け付けてくれ、リムジェット除去後の推奨感度はベースより一段上のISO 400。明るい屋外の日差しに抑制の効いたシネマティックな色をもたらすとしてよく名前が挙がる。$ja$ WHERE slug = 'marix400d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kodak Vision3 500T(5219)をベースに、リムジェットを除去してC-41に対応させたもの。タングステン光(3200K)にバランスを合わせているため、デイライト下では青みがかり、そのトーンがトレードマークになっている。夜の都市風景や人工光下の室内ルポルタージュで最もよく名前が挙がるフィルムのひとつ。$ja$ WHERE slug = 'marix800t' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Kodak Vision3 5203(50D)からリムジェットを除去した低感度ライン。粒子はほとんど見えず色は濃く出て、強い真昼の日差しや風景でよく選ばれる。C-41。$ja$ WHERE slug = 'reflxlab50d' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$富士フイルムの一般向けE-6リバーサルフィルム。よく整ったデイライトの発色で知られ、2010年にSensiaライン全体が生産終了した。現在は中古市場と冷凍保存品で見かけるのみ。$ja$ WHERE slug = 'sensia100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Sensiaラインの中間の感度。日常のスナップや旅行向けのバランスの良いE-6リバーサルで、2010年にラインの他の製品とともに生産終了した。$ja$ WHERE slug = 'sensia200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Sensiaラインで最も高感度。室内や低照度でのE-6リバーサル撮影を可能にし、風景のルポルタージュでよく名前が挙がった。2010年にラインの他の製品とともに生産終了。$ja$ WHERE slug = 'sensia400' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Silberraの限定版の一般向けカラーネガ、ISO 100。C-41処理。$ja$ WHERE slug = 'silberracolor100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Silberraが2021年に発売した一般向けカラーネガ、ISO 160。C-41処理で、温かなトーン。$ja$ WHERE slug = 'silberracolor160' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Silberraが2021年に発表した限定版の一般向けカラーネガ、ISO 50。C-41処理で、温かなトーン。$ja$ WHERE slug = 'silberracolor50' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Silberraのオルソクロマチック・モノクロネガ、ISO 50。赤に感光しないため、肌や唇が暗めに写るクラシックなグレースケール。$ja$ WHERE slug = 'silberraorta50' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Silberraのオルソクロマチック・モノクロネガ、ISO 80。グレースケールは一段柔らかく、ラチチュードもやや広い。$ja$ WHERE slug = 'silberraorta80' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Silberraのパンクロマチック・モノクロネガ、ISO 100。PANシリーズの標準感度で、同じ乳剤はUltima 100としても販売されている。$ja$ WHERE slug = 'silberrapan100' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Silberraのパンクロマチック・モノクロネガ、ISO 160。Ultima 160としても販売され、粒子はざらつきながらも落ち着いた印象。$ja$ WHERE slug = 'silberrapan160' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Silberraの限定版パンクロマチック・モノクロネガ、ISO 200。Ultima 200としても販売されている。$ja$ WHERE slug = 'silberrapan200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$ロシアのブランドSilberraのパンクロマチック・モノクロネガ、ISO 50。細かな粒子と高い解像力で知られ、同じ乳剤はプレミアムパッケージのUltima 50としても販売されている。$ja$ WHERE slug = 'silberrapan50' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$Ultimaと同じベースから出発したSilberraの低価格モノクロネガ。標準のISO 200露光のほか、100や400への減感・増感にもよく耐える。$ja$ WHERE slug = 'silberrau200' AND description_ja IS NULL;
UPDATE public.films SET description_ja = $ja$SilberraのUシリーズのISO 400モノクロネガ。同じベースで作られた、増感の余地がある低価格ライン。$ja$ WHERE slug = 'silberrau400' AND description_ja IS NULL;

