UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$カメラ写真館$ja$), address_ja = COALESCE(address_ja, $ja$仁川広域市 南洞区 ソンマル路44番ギル 11-13 2階$ja$), features_ja = COALESCE(features_ja, $ja$暗室体験ができる。$ja$) WHERE name = '카메라사진관' AND region = '인천';
UPDATE public.labs SET name_ja = COALESCE(name_ja, $ja$ヘダンファ写真館$ja$), address_ja = COALESCE(address_ja, $ja$仁川広域市 中区 済物梁路 288 1階$ja$), features_ja = COALESCE(features_ja, $ja$カラー現像5,000ウォン(3本で13,000ウォン)、高解像度スキャンのオプションあり。モノクロ現像+スキャン12,000ウォン。証明写真スタジオも兼ねる。$ja$) WHERE name = '해당화사진관' AND region = '인천';

